-- >>>>>>>>>> schema/00_create_database.sql
-- ====================================================================
-- Mess Finder database - create the database
-- This file is safe to run more than once: it never drops anything.
-- To start again from zero, use scripts/reset_database.sql first.
-- ====================================================================

CREATE DATABASE IF NOT EXISTS mess_finder
    DEFAULT CHARACTER SET utf8mb4
    DEFAULT COLLATE utf8mb4_0900_ai_ci;

USE mess_finder;


-- >>>>>>>>>> schema/01_users_and_locations.sql
-- ====================================================================
-- Mess Finder database - Users and locations
-- Tables: areas, universities, users, student_profiles, manager_profiles
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- areas: Areas of the city, used to filter messes
-- --------------------------------------------------------------------
CREATE TABLE areas (
    area_id   INT NOT NULL AUTO_INCREMENT,
    area_name VARCHAR(80) NOT NULL,
    city      VARCHAR(50) NOT NULL DEFAULT 'Dhaka',

    CONSTRAINT pk_areas PRIMARY KEY (area_id),
    CONSTRAINT uq_areas_area_name UNIQUE (area_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Areas of the city, used to filter messes';

-- --------------------------------------------------------------------
-- universities: Universities with coordinates for the nearby search
-- --------------------------------------------------------------------
CREATE TABLE universities (
    university_id INT NOT NULL AUTO_INCREMENT,
    name          VARCHAR(150) NOT NULL,
    short_name    VARCHAR(20),
    area_id       INT NOT NULL,
    latitude      DECIMAL(9,6) NOT NULL,
    longitude     DECIMAL(9,6) NOT NULL,

    CONSTRAINT pk_universities PRIMARY KEY (university_id),
    CONSTRAINT uq_universities_name UNIQUE (name),
    CONSTRAINT fk_universities_area FOREIGN KEY (area_id)
        REFERENCES areas (area_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_uni_lat CHECK (latitude BETWEEN -90 AND 90),  -- valid latitude
    CONSTRAINT chk_uni_lng CHECK (longitude BETWEEN -180 AND 180)  -- valid longitude
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Universities with coordinates for the nearby search';

-- --------------------------------------------------------------------
-- users: All accounts: student, manager and admin
-- --------------------------------------------------------------------
CREATE TABLE users (
    user_id       INT NOT NULL AUTO_INCREMENT,
    full_name     VARCHAR(100) NOT NULL,
    email         VARCHAR(120) NOT NULL,
    phone         VARCHAR(20) NOT NULL,  -- unique, managers search students by phone
    password_hash VARCHAR(255) NOT NULL,
    role          ENUM('student','manager','admin') NOT NULL,
    is_active     BOOLEAN NOT NULL DEFAULT 1,  -- 0 = blocked (soft delete)
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_users PRIMARY KEY (user_id),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT uq_users_phone UNIQUE (phone),
    CONSTRAINT uq_user_role UNIQUE (user_id, role)  -- lets profile tables point at (user_id, role)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'All accounts: student, manager and admin';

-- --------------------------------------------------------------------
-- student_profiles: Extra details for student accounts (1:1 with users)
-- --------------------------------------------------------------------
CREATE TABLE student_profiles (
    student_id    INT NOT NULL,
    role          ENUM('student','manager','admin') NOT NULL DEFAULT 'student',  -- always 'student'
    university_id INT NOT NULL,
    student_roll  VARCHAR(30),
    department    VARCHAR(80),
    gender        ENUM('male','female') NOT NULL,

    CONSTRAINT pk_student_profiles PRIMARY KEY (student_id),
    CONSTRAINT fk_student_profiles_user FOREIGN KEY (student_id, role)
        REFERENCES users (user_id, role)
        ON DELETE RESTRICT ON UPDATE NO ACTION,  -- a manager account cannot get a student profile
    CONSTRAINT fk_student_profiles_university FOREIGN KEY (university_id)
        REFERENCES universities (university_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_sp_role CHECK (role = 'student')  -- role is always 'student'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Extra details for student accounts (1:1 with users)';

-- --------------------------------------------------------------------
-- manager_profiles: Extra details for manager accounts (1:1 with users)
-- --------------------------------------------------------------------
CREATE TABLE manager_profiles (
    manager_id  INT NOT NULL,
    role        ENUM('student','manager','admin') NOT NULL DEFAULT 'manager',  -- always 'manager'
    nid_no      VARCHAR(20) NOT NULL,
    address     VARCHAR(255),
    is_verified BOOLEAN NOT NULL DEFAULT 0,  -- admin verifies managers

    CONSTRAINT pk_manager_profiles PRIMARY KEY (manager_id),
    CONSTRAINT uq_manager_profiles_nid_no UNIQUE (nid_no),
    CONSTRAINT fk_manager_profiles_user FOREIGN KEY (manager_id, role)
        REFERENCES users (user_id, role)
        ON DELETE RESTRICT ON UPDATE NO ACTION,  -- a student account cannot get a manager profile
    CONSTRAINT chk_mp_role CHECK (role = 'manager')  -- role is always 'manager'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Extra details for manager accounts (1:1 with users)';


-- >>>>>>>>>> schema/02_mess_setup.sql
-- ====================================================================
-- Mess Finder database - Mess setup (mess, facilities, rooms, seats)
-- Tables: messes, facilities, mess_facilities, mess_universities, rooms, seats, seat_rent_log
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- messes: Mess details, one mess per manager
-- --------------------------------------------------------------------
CREATE TABLE messes (
    mess_id           INT NOT NULL AUTO_INCREMENT,
    manager_id        INT NOT NULL,  -- UNIQUE: one manager runs one mess
    area_id           INT NOT NULL,
    mess_name         VARCHAR(120) NOT NULL,
    address           VARCHAR(255) NOT NULL,
    description       TEXT,
    mess_type         ENUM('boys','girls') NOT NULL,
    rules             TEXT,
    established_year  YEAR,
    contact_phone     VARCHAR(20) NOT NULL,  -- with country code, e.g. 8801711000000
    contact_whatsapp  VARCHAR(20),
    has_meal          BOOLEAN NOT NULL DEFAULT 0,
    meal_cost_monthly DECIMAL(10,2),
    utility_included  BOOLEAN NOT NULL DEFAULT 0,
    advance_amount    DECIMAL(10,2) NOT NULL DEFAULT 0,
    latitude          DECIMAL(9,6) NOT NULL,
    longitude         DECIMAL(9,6) NOT NULL,
    status            ENUM('pending','verified','suspended','closed') NOT NULL DEFAULT 'pending',  -- closed = soft delete
    created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_messes PRIMARY KEY (mess_id),
    CONSTRAINT uq_messes_manager UNIQUE (manager_id),  -- one manager, one mess
    FULLTEXT KEY ftx_messes_description (description),
    KEY idx_messes_area_id_mess_type_status (area_id, mess_type, status),
    CONSTRAINT fk_messes_manager FOREIGN KEY (manager_id)
        REFERENCES manager_profiles (manager_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_messes_area FOREIGN KEY (area_id)
        REFERENCES areas (area_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_mess_meal CHECK (has_meal = 1 OR meal_cost_monthly IS NULL),  -- meal cost only if the mess serves meals
    CONSTRAINT chk_mess_meal_cost CHECK (meal_cost_monthly IS NULL OR meal_cost_monthly >= 0),  -- meal cost cannot be negative
    CONSTRAINT chk_mess_advance CHECK (advance_amount >= 0),  -- advance cannot be negative
    CONSTRAINT chk_mess_lat CHECK (latitude BETWEEN -90 AND 90),  -- valid latitude
    CONSTRAINT chk_mess_lng CHECK (longitude BETWEEN -180 AND 180)  -- valid longitude
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Mess details, one mess per manager';

-- --------------------------------------------------------------------
-- facilities: Facility list: wifi, gas, generator...
-- --------------------------------------------------------------------
CREATE TABLE facilities (
    facility_id   INT NOT NULL AUTO_INCREMENT,
    facility_name VARCHAR(50) NOT NULL,

    CONSTRAINT pk_facilities PRIMARY KEY (facility_id),
    CONSTRAINT uq_facilities_facility_name UNIQUE (facility_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Facility list: wifi, gas, generator...';

-- --------------------------------------------------------------------
-- mess_facilities: Facilities a mess has (many-to-many)
-- --------------------------------------------------------------------
CREATE TABLE mess_facilities (
    mess_id     INT NOT NULL,
    facility_id INT NOT NULL,

    CONSTRAINT pk_mess_facilities PRIMARY KEY (mess_id, facility_id),
    CONSTRAINT fk_mess_facilities_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_mess_facilities_facility FOREIGN KEY (facility_id)
        REFERENCES facilities (facility_id)
        ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Facilities a mess has (many-to-many)';

-- --------------------------------------------------------------------
-- mess_universities: Nearby universities of a mess with distance (many-to-many)
-- --------------------------------------------------------------------
CREATE TABLE mess_universities (
    mess_id       INT NOT NULL,
    university_id INT NOT NULL,
    distance_km   DECIMAL(4,1) NOT NULL,

    CONSTRAINT pk_mess_universities PRIMARY KEY (mess_id, university_id),
    CONSTRAINT fk_mess_universities_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_mess_universities_university FOREIGN KEY (university_id)
        REFERENCES universities (university_id)
        ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT chk_mu_dist CHECK (distance_km >= 0)  -- distance cannot be negative
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Nearby universities of a mess with distance (many-to-many)';

-- --------------------------------------------------------------------
-- rooms: Rooms inside a mess
-- --------------------------------------------------------------------
CREATE TABLE rooms (
    room_id           INT NOT NULL AUTO_INCREMENT,
    mess_id           INT NOT NULL,
    room_no           VARCHAR(10) NOT NULL,
    floor_no          TINYINT,
    has_attached_bath BOOLEAN NOT NULL DEFAULT 0,
    has_balcony       BOOLEAN NOT NULL DEFAULT 0,
    is_active         BOOLEAN NOT NULL DEFAULT 1,  -- 0 = soft delete

    CONSTRAINT pk_rooms PRIMARY KEY (room_id),
    CONSTRAINT uq_room_no UNIQUE (mess_id, room_no),  -- no duplicate room number inside one mess
    CONSTRAINT fk_rooms_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Rooms inside a mess';

-- --------------------------------------------------------------------
-- seats: Seats inside a room, rent is set per seat
-- --------------------------------------------------------------------
CREATE TABLE seats (
    seat_id      INT NOT NULL AUTO_INCREMENT,
    room_id      INT NOT NULL,
    seat_label   VARCHAR(10) NOT NULL,
    monthly_rent DECIMAL(10,2) NOT NULL,
    status       ENUM('available','booked','inactive') NOT NULL DEFAULT 'available',  -- inactive = soft delete

    CONSTRAINT pk_seats PRIMARY KEY (seat_id),
    CONSTRAINT uq_seat_label UNIQUE (room_id, seat_label),  -- no duplicate seat label inside one room
    CONSTRAINT fk_seats_room FOREIGN KEY (room_id)
        REFERENCES rooms (room_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_seat_rent CHECK (monthly_rent > 0)  -- rent must be positive
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Seats inside a room, rent is set per seat';

-- --------------------------------------------------------------------
-- seat_rent_log: History of seat rent changes (filled by a trigger)
-- --------------------------------------------------------------------
CREATE TABLE seat_rent_log (
    log_id     INT NOT NULL AUTO_INCREMENT,
    seat_id    INT NOT NULL,
    old_rent   DECIMAL(10,2) NOT NULL,
    new_rent   DECIMAL(10,2) NOT NULL,
    changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_seat_rent_log PRIMARY KEY (log_id),
    CONSTRAINT fk_seat_rent_log_seat FOREIGN KEY (seat_id)
        REFERENCES seats (seat_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_log_diff CHECK (old_rent <> new_rent)  -- old and new rent must differ
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'History of seat rent changes (filled by a trigger)';


-- >>>>>>>>>> schema/03_newsfeed_and_social.sql
-- ====================================================================
-- Mess Finder database - Newsfeed and social (posts, comments, interests)
-- Tables: vacancy_posts, post_seats, seat_wanted_posts, post_comments, interests
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- vacancy_posts: Vacancy posts made by managers
-- --------------------------------------------------------------------
CREATE TABLE vacancy_posts (
    post_id        INT NOT NULL AUTO_INCREMENT,
    mess_id        INT NOT NULL,
    title          VARCHAR(150) NOT NULL,
    description    TEXT,
    available_from DATE NOT NULL,
    status         ENUM('open','closed','expired','removed') NOT NULL DEFAULT 'open',  -- removed = taken down by admin
    created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_vacancy_posts PRIMARY KEY (post_id),
    CONSTRAINT uq_post_mess UNIQUE (post_id, mess_id),  -- lets interests point at (post_id, mess_id)
    CONSTRAINT fk_vacancy_posts_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Vacancy posts made by managers';

-- --------------------------------------------------------------------
-- post_seats: Seats advertised in a vacancy post (many-to-many)
-- --------------------------------------------------------------------
CREATE TABLE post_seats (
    post_id INT NOT NULL,
    seat_id INT NOT NULL,

    CONSTRAINT pk_post_seats PRIMARY KEY (post_id, seat_id),
    CONSTRAINT fk_post_seats_post FOREIGN KEY (post_id)
        REFERENCES vacancy_posts (post_id)
        ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT fk_post_seats_seat FOREIGN KEY (seat_id)
        REFERENCES seats (seat_id)
        ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Seats advertised in a vacancy post (many-to-many)';

-- --------------------------------------------------------------------
-- seat_wanted_posts: Seat wanted posts made by students
-- --------------------------------------------------------------------
CREATE TABLE seat_wanted_posts (
    wanted_id     INT NOT NULL AUTO_INCREMENT,
    student_id    INT NOT NULL,
    title         VARCHAR(150) NOT NULL,
    description   TEXT,
    area_id       INT,  -- preferred area
    university_id INT,
    budget_min    DECIMAL(10,2),
    budget_max    DECIMAL(10,2),
    mess_type     ENUM('boys','girls') NOT NULL,
    needed_from   DATE NOT NULL,
    status        ENUM('open','closed','expired','removed') NOT NULL DEFAULT 'open',  -- removed = taken down by admin
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_seat_wanted_posts PRIMARY KEY (wanted_id),
    CONSTRAINT fk_seat_wanted_posts_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_seat_wanted_posts_area FOREIGN KEY (area_id)
        REFERENCES areas (area_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_seat_wanted_posts_university FOREIGN KEY (university_id)
        REFERENCES universities (university_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_budget CHECK (budget_min IS NULL OR budget_max IS NULL OR budget_min <= budget_max)  -- minimum budget cannot be above maximum
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Seat wanted posts made by students';

-- --------------------------------------------------------------------
-- post_comments: Comments on newsfeed posts, either post type
-- --------------------------------------------------------------------
CREATE TABLE post_comments (
    comment_id      INT NOT NULL AUTO_INCREMENT,
    user_id         INT NOT NULL,  -- student or manager
    vacancy_post_id INT,
    wanted_post_id  INT,
    body            VARCHAR(500) NOT NULL,
    is_deleted      BOOLEAN NOT NULL DEFAULT 0,  -- 1 = soft delete
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_post_comments PRIMARY KEY (comment_id),
    KEY idx_post_comments_vacancy_post_id_created_at (vacancy_post_id, created_at),
    KEY idx_post_comments_wanted_post_id_created_at (wanted_post_id, created_at),
    CONSTRAINT fk_post_comments_user FOREIGN KEY (user_id)
        REFERENCES users (user_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_post_comments_vacancy_post FOREIGN KEY (vacancy_post_id)
        REFERENCES vacancy_posts (post_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_post_comments_wanted_post FOREIGN KEY (wanted_post_id)
        REFERENCES seat_wanted_posts (wanted_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_one_post CHECK ((vacancy_post_id IS NULL) <> (wanted_post_id IS NULL))  -- a comment belongs to exactly one post
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Comments on newsfeed posts, either post type';

-- --------------------------------------------------------------------
-- interests: Messes a student marked as Interested
-- --------------------------------------------------------------------
CREATE TABLE interests (
    student_id INT NOT NULL,
    mess_id    INT NOT NULL,
    post_id    INT,  -- post the student pressed Interested on (optional)
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_interests PRIMARY KEY (student_id, mess_id),
    CONSTRAINT fk_interests_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_interests_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_interests_post FOREIGN KEY (post_id, mess_id)
        REFERENCES vacancy_posts (post_id, mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION  -- post must belong to the same mess, skipped when post_id is NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Messes a student marked as Interested';


-- >>>>>>>>>> schema/04_members_and_rent.sql
-- ====================================================================
-- Mess Finder database - Members, monthly rent and payments
-- Tables: mess_members, rent_dues, payments
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- mess_members: People living (or who lived) in a seat, replaces booking
-- --------------------------------------------------------------------
CREATE TABLE mess_members (
    member_id         INT NOT NULL AUTO_INCREMENT,
    seat_id           INT NOT NULL,
    student_id        INT,  -- set when linked to a student account
    full_name         VARCHAR(100) NOT NULL,
    phone             VARCHAR(20) NOT NULL,
    gender            ENUM('male','female') NOT NULL,
    occupation        VARCHAR(100),
    monthly_rent      DECIMAL(10,2) NOT NULL,  -- rent agreed at joining (a snapshot)
    advance_amount    DECIMAL(10,2) NOT NULL DEFAULT 0,  -- agreed advance, real money goes in payments
    join_date         DATE NOT NULL,
    leave_date        DATE,
    status            ENUM('active','left') NOT NULL DEFAULT 'active',
    active_seat_id    INT GENERATED ALWAYS AS (IF(status = 'active', seat_id, NULL)) STORED,  -- seat id while active, else NULL
    active_student_id INT GENERATED ALWAYS AS (IF(status = 'active', student_id, NULL)) STORED,  -- student id while active, else NULL
    created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_mess_members PRIMARY KEY (member_id),
    CONSTRAINT uq_mess_members_active_seat UNIQUE (active_seat_id),
    CONSTRAINT uq_mess_members_active_student UNIQUE (active_student_id),
    CONSTRAINT fk_mess_members_seat FOREIGN KEY (seat_id)
        REFERENCES seats (seat_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_mess_members_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_member_rent CHECK (monthly_rent > 0),  -- rent must be positive
    CONSTRAINT chk_member_adv CHECK (advance_amount >= 0),  -- advance cannot be negative
    CONSTRAINT chk_member_leave CHECK ((status = 'active' AND leave_date IS NULL) OR (status = 'left' AND leave_date IS NOT NULL AND leave_date >= join_date))  -- active: no leave date; left: leave date on or after join date
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'People living (or who lived) in a seat, replaces booking';

-- --------------------------------------------------------------------
-- rent_dues: Monthly rent due for each member (created by an event)
-- --------------------------------------------------------------------
CREATE TABLE rent_dues (
    due_id    INT NOT NULL AUTO_INCREMENT,
    member_id INT NOT NULL,
    due_month DATE NOT NULL,  -- first day of the month
    amount    DECIMAL(10,2) NOT NULL,
    due_date  DATE NOT NULL,  -- last day to pay
    status    ENUM('due','partial','paid','overdue') NOT NULL DEFAULT 'due',

    CONSTRAINT pk_rent_dues PRIMARY KEY (due_id),
    CONSTRAINT uq_member_month UNIQUE (member_id, due_month),  -- one due per member per month
    CONSTRAINT uq_due_member UNIQUE (due_id, member_id),  -- lets payments point at (due_id, member_id)
    CONSTRAINT fk_rent_dues_member FOREIGN KEY (member_id)
        REFERENCES mess_members (member_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_due_month CHECK (DAY(due_month) = 1),  -- due month is always the 1st
    CONSTRAINT chk_due_amount CHECK (amount > 0),  -- amount must be positive
    CONSTRAINT chk_due_date CHECK (due_date >= due_month)  -- deadline is not before the month starts
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Monthly rent due for each member (created by an event)';

-- --------------------------------------------------------------------
-- payments: Money received from members, advance or monthly
-- --------------------------------------------------------------------
CREATE TABLE payments (
    payment_id   INT NOT NULL AUTO_INCREMENT,
    member_id    INT NOT NULL,
    due_id       INT,  -- NULL for advance payments
    amount       DECIMAL(10,2) NOT NULL,
    payment_type ENUM('advance','monthly') NOT NULL,
    method       ENUM('cash','bkash','nagad') NOT NULL,
    paid_at      DATETIME NOT NULL,

    CONSTRAINT pk_payments PRIMARY KEY (payment_id),
    CONSTRAINT fk_payments_member FOREIGN KEY (member_id)
        REFERENCES mess_members (member_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_payments_due FOREIGN KEY (due_id, member_id)
        REFERENCES rent_dues (due_id, member_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,  -- a payment can only settle its own member's due
    CONSTRAINT chk_pay_amount CHECK (amount > 0),  -- amount must be positive
    CONSTRAINT chk_pay_due CHECK ((payment_type = 'monthly') = (due_id IS NOT NULL))  -- monthly payments need a due, advance payments must not have one
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Money received from members, advance or monthly';


-- >>>>>>>>>> schema/05_reviews_visits_and_chat.sql
-- ====================================================================
-- Mess Finder database - Reviews, visit requests and chat
-- Tables: reviews, visit_requests, conversations, messages
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- reviews: Reviews by current or ex members, with manager reply
-- --------------------------------------------------------------------
CREATE TABLE reviews (
    review_id          INT NOT NULL AUTO_INCREMENT,
    mess_id            INT NOT NULL,
    student_id         INT NOT NULL,
    rating             TINYINT NOT NULL,  -- overall rating
    cleanliness_rating TINYINT,
    safety_rating      TINYINT,
    food_rating        TINYINT,
    comment            VARCHAR(500),
    manager_reply      VARCHAR(500),
    replied_at         TIMESTAMP,
    created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_reviews PRIMARY KEY (review_id),
    CONSTRAINT uq_review UNIQUE (mess_id, student_id),  -- one review per student per mess
    CONSTRAINT fk_reviews_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_reviews_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_rating CHECK (rating BETWEEN 1 AND 5),  -- rating from 1 to 5
    CONSTRAINT chk_rating_clean CHECK (cleanliness_rating IS NULL OR cleanliness_rating BETWEEN 1 AND 5),  -- rating from 1 to 5
    CONSTRAINT chk_rating_safe CHECK (safety_rating IS NULL OR safety_rating BETWEEN 1 AND 5),  -- rating from 1 to 5
    CONSTRAINT chk_rating_food CHECK (food_rating IS NULL OR food_rating BETWEEN 1 AND 5),  -- rating from 1 to 5
    CONSTRAINT chk_reply_pair CHECK ((manager_reply IS NULL) = (replied_at IS NULL))  -- reply text and reply time go together
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Reviews by current or ex members, with manager reply';

-- --------------------------------------------------------------------
-- visit_requests: Requests from students to visit a mess
-- --------------------------------------------------------------------
CREATE TABLE visit_requests (
    visit_id     INT NOT NULL AUTO_INCREMENT,
    student_id   INT NOT NULL,
    mess_id      INT NOT NULL,
    visit_time   DATETIME NOT NULL,
    status       ENUM('pending','confirmed','rejected','cancelled','completed') NOT NULL DEFAULT 'pending',
    student_note VARCHAR(255),
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_visit_requests PRIMARY KEY (visit_id),
    CONSTRAINT fk_visit_requests_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_visit_requests_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Requests from students to visit a mess';

-- --------------------------------------------------------------------
-- conversations: One chat thread per student and mess
-- --------------------------------------------------------------------
CREATE TABLE conversations (
    conversation_id INT NOT NULL AUTO_INCREMENT,
    mess_id         INT NOT NULL,
    student_id      INT NOT NULL,
    last_message_at TIMESTAMP,  -- kept up to date by a trigger
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_conversations PRIMARY KEY (conversation_id),
    CONSTRAINT uq_conversation UNIQUE (mess_id, student_id),  -- one chat thread per student per mess
    CONSTRAINT fk_conversations_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_conversations_student FOREIGN KEY (student_id)
        REFERENCES student_profiles (student_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'One chat thread per student and mess';

-- --------------------------------------------------------------------
-- messages: Chat messages
-- --------------------------------------------------------------------
CREATE TABLE messages (
    message_id      INT NOT NULL AUTO_INCREMENT,
    conversation_id INT NOT NULL,
    sender_id       INT NOT NULL,
    body            VARCHAR(1000) NOT NULL,
    is_read         BOOLEAN NOT NULL DEFAULT 0,
    sent_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_messages PRIMARY KEY (message_id),
    KEY idx_messages_conversation_id_sent_at (conversation_id, sent_at),
    CONSTRAINT fk_messages_conversation FOREIGN KEY (conversation_id)
        REFERENCES conversations (conversation_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_messages_sender FOREIGN KEY (sender_id)
        REFERENCES users (user_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_msg_body CHECK (CHAR_LENGTH(TRIM(body)) > 0)  -- no empty messages
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Chat messages';


-- >>>>>>>>>> schema/06_admin_and_notifications.sql
-- ====================================================================
-- Mess Finder database - Complaints and notifications
-- Tables: complaints, notifications
-- Run the files in this folder in number order.
-- ====================================================================
USE mess_finder;

-- --------------------------------------------------------------------
-- complaints: Complaints filed by users
-- --------------------------------------------------------------------
CREATE TABLE complaints (
    complaint_id    INT NOT NULL AUTO_INCREMENT,
    complainant_id  INT NOT NULL,  -- who filed it
    against_user_id INT,
    mess_id         INT,
    subject         VARCHAR(150) NOT NULL,
    description     TEXT NOT NULL,
    status          ENUM('open','in_review','resolved','dismissed') NOT NULL DEFAULT 'open',
    admin_note      VARCHAR(255),
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at     TIMESTAMP,

    CONSTRAINT pk_complaints PRIMARY KEY (complaint_id),
    CONSTRAINT fk_complaints_complainant FOREIGN KEY (complainant_id)
        REFERENCES users (user_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_complaints_against_user FOREIGN KEY (against_user_id)
        REFERENCES users (user_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT fk_complaints_mess FOREIGN KEY (mess_id)
        REFERENCES messes (mess_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT chk_comp_target CHECK (against_user_id IS NOT NULL OR mess_id IS NOT NULL),  -- a complaint is about a user or a mess
    CONSTRAINT chk_comp_self CHECK (against_user_id IS NULL OR against_user_id <> complainant_id),  -- cannot complain about yourself
    CONSTRAINT chk_comp_resolved CHECK ((status IN ('resolved','dismissed')) = (resolved_at IS NOT NULL))  -- resolved_at only for resolved or dismissed complaints
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Complaints filed by users';

-- --------------------------------------------------------------------
-- notifications: Notifications shown to users
-- --------------------------------------------------------------------
CREATE TABLE notifications (
    notification_id INT NOT NULL AUTO_INCREMENT,
    user_id         INT NOT NULL,
    message         VARCHAR(255) NOT NULL,
    is_read         BOOLEAN NOT NULL DEFAULT 0,
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_notifications PRIMARY KEY (notification_id),
    KEY idx_notifications_user_id_is_read_created_at (user_id, is_read, created_at),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id)
        REFERENCES users (user_id)
        ON DELETE RESTRICT ON UPDATE NO ACTION
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'Notifications shown to users';


