-- >>>>>>>>>> views/01_v_available_seats.sql
-- ====================================================================
-- v_available_seats
-- Free seats of verified messes, with the room, mess and area details.
-- Used by: Browse messes (free seat count) and the Mess details page.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_available_seats AS
SELECT s.seat_id,
       s.seat_label,
       s.monthly_rent,
       r.room_id,
       r.room_no,
       r.floor_no,
       r.has_attached_bath,
       r.has_balcony,
       me.mess_id,
       me.mess_name,
       me.mess_type,
       a.area_id,
       a.area_name
FROM seats AS s
JOIN rooms  AS r  ON r.room_id  = s.room_id
JOIN messes AS me ON me.mess_id = r.mess_id
JOIN areas  AS a  ON a.area_id  = me.area_id
WHERE s.status = 'available'
  AND r.is_active = 1
  AND me.status = 'verified';


-- >>>>>>>>>> views/02_v_mess_summary.sql
-- ====================================================================
-- v_mess_summary
-- One row per mess with everything the mess card needs: area, rent range,
-- free seats and rating. Seats that are inactive are not counted.
-- Used by: Browse messes, Home page (top rated), Interested list.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_mess_summary AS
SELECT me.mess_id,
       me.manager_id,
       me.mess_name,
       me.mess_type,
       me.address,
       me.status,
       me.has_meal,
       me.meal_cost_monthly,
       me.utility_included,
       me.advance_amount,
       me.latitude,
       me.longitude,
       a.area_id,
       a.area_name,
       COALESCE(ss.total_seats, 0)  AS total_seats,
       COALESCE(ss.free_seats, 0)   AS free_seats,
       ss.min_rent,
       ss.max_rent,
       rv.avg_rating,
       COALESCE(rv.review_count, 0) AS review_count
FROM messes AS me
JOIN areas AS a ON a.area_id = me.area_id
LEFT JOIN (
    -- seat numbers per mess
    SELECT r.mess_id,
           COUNT(*)                     AS total_seats,
           SUM(s.status = 'available')  AS free_seats,
           MIN(s.monthly_rent)          AS min_rent,
           MAX(s.monthly_rent)          AS max_rent
    FROM rooms AS r
    JOIN seats AS s ON s.room_id = r.room_id
    WHERE r.is_active = 1 AND s.status <> 'inactive'
    GROUP BY r.mess_id
) AS ss ON ss.mess_id = me.mess_id
LEFT JOIN (
    -- rating numbers per mess
    SELECT mess_id,
           ROUND(AVG(rating), 2) AS avg_rating,
           COUNT(*)              AS review_count
    FROM reviews
    GROUP BY mess_id
) AS rv ON rv.mess_id = me.mess_id;


-- >>>>>>>>>> views/03_v_mess_history.sql
-- ====================================================================
-- v_mess_history
-- The "History" section of the Mess details page: only numbers, no names.
-- (The names of ex-members are shown to the manager only.)
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_mess_history AS
SELECT me.mess_id,
       me.established_year,
       COUNT(m.member_id)                 AS total_members_ever,
       COALESCE(SUM(m.status = 'active'), 0) AS current_members
FROM messes AS me
LEFT JOIN rooms AS r ON r.mess_id = me.mess_id
LEFT JOIN seats AS s ON s.room_id = r.room_id
LEFT JOIN mess_members AS m ON m.seat_id = s.seat_id
GROUP BY me.mess_id, me.established_year;


-- >>>>>>>>>> views/04_v_member_dues.sql
-- ====================================================================
-- v_member_dues
-- One row per member with the money side: how much was due, how much was
-- paid, what is still owed, and the status of this month's rent.
-- Used by: Manager Members page, Manager dashboard, student's My mess page.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_member_dues AS
WITH paid_per_due AS (
    -- money received for each due (advance payments have no due, so they are left out)
    SELECT due_id, SUM(amount) AS paid
    FROM payments
    WHERE due_id IS NOT NULL
    GROUP BY due_id
),
totals_per_member AS (
    SELECT d.member_id,
           SUM(d.amount)                AS total_due,
           SUM(COALESCE(p.paid, 0))     AS total_paid,
           SUM(d.status = 'overdue')    AS overdue_count
    FROM rent_dues AS d
    LEFT JOIN paid_per_due AS p ON p.due_id = d.due_id
    GROUP BY d.member_id
)
SELECT m.member_id,
       r.mess_id,
       m.full_name,
       m.phone,
       m.student_id,
       r.room_no,
       s.seat_label,
       m.monthly_rent,
       m.status                                           AS member_status,
       m.join_date,
       m.leave_date,
       COALESCE(t.total_due, 0)                           AS total_due,
       COALESCE(t.total_paid, 0)                          AS total_paid,
       COALESCE(t.total_due, 0) - COALESCE(t.total_paid, 0) AS outstanding,
       COALESCE(t.overdue_count, 0)                       AS overdue_count,
       cm.status                                          AS current_month_status
FROM mess_members AS m
JOIN seats AS s ON s.seat_id = m.seat_id
JOIN rooms AS r ON r.room_id = s.room_id
LEFT JOIN totals_per_member AS t ON t.member_id = m.member_id
LEFT JOIN rent_dues AS cm
       ON cm.member_id = m.member_id
      AND cm.due_month = DATE_FORMAT(CURDATE(), '%Y-%m-01');


-- >>>>>>>>>> views/05_v_room_seat_status.sql
-- ====================================================================
-- v_room_seat_status
-- Every seat with its room and the person who lives in it (NULL when free).
-- Used by: Manager Room-wise seats page and the Rooms and seats section
-- of the Mess details page.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_room_seat_status AS
SELECT r.mess_id,
       r.room_id,
       r.room_no,
       r.floor_no,
       r.has_attached_bath,
       r.has_balcony,
       r.is_active          AS room_is_active,
       s.seat_id,
       s.seat_label,
       s.monthly_rent,
       s.status             AS seat_status,
       m.member_id,
       m.full_name          AS member_name,
       m.phone              AS member_phone,
       m.join_date          AS member_since
FROM rooms AS r
JOIN seats AS s ON s.room_id = r.room_id
-- active_seat_id is filled only while a member is active, so this finds the current person
LEFT JOIN mess_members AS m ON m.active_seat_id = s.seat_id;


-- >>>>>>>>>> views/06_v_manager_stats.sql
-- ====================================================================
-- v_manager_stats
-- The overview cards of the Manager dashboard, one row per mess.
-- Total outstanding counts everybody who still owes money, also ex-members.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_manager_stats AS
WITH seat_counts AS (
    SELECT r.mess_id,
           SUM(s.status <> 'inactive')  AS total_seats,
           SUM(s.status = 'available')  AS free_seats,
           SUM(s.status = 'booked')     AS booked_seats
    FROM rooms AS r
    JOIN seats AS s ON s.room_id = r.room_id
    WHERE r.is_active = 1
    GROUP BY r.mess_id
),
member_counts AS (
    SELECT mess_id,
           SUM(member_status = 'active')       AS active_members,
           SUM(outstanding > 0)               AS members_with_dues,
           SUM(GREATEST(outstanding, 0))      AS total_outstanding
    FROM v_member_dues
    GROUP BY mess_id
),
collected_this_month AS (
    SELECT r.mess_id, SUM(p.amount) AS collected
    FROM payments AS p
    JOIN mess_members AS m ON m.member_id = p.member_id
    JOIN seats AS s ON s.seat_id = m.seat_id
    JOIN rooms AS r ON r.room_id = s.room_id
    WHERE p.paid_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
      AND p.paid_at <  DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
    GROUP BY r.mess_id
)
SELECT me.mess_id,
       me.manager_id,
       me.mess_name,
       COALESCE(sc.total_seats, 0)        AS total_seats,
       COALESCE(sc.free_seats, 0)         AS free_seats,
       COALESCE(sc.booked_seats, 0)       AS booked_seats,
       ROUND(100 * COALESCE(sc.booked_seats, 0) / NULLIF(sc.total_seats, 0), 1) AS occupancy_percent,
       COALESCE(mc.active_members, 0)     AS active_members,
       COALESCE(mc.members_with_dues, 0)  AS members_with_dues,
       COALESCE(mc.total_outstanding, 0)  AS total_outstanding,
       COALESCE(c.collected, 0)           AS collected_this_month
FROM messes AS me
LEFT JOIN seat_counts          AS sc ON sc.mess_id = me.mess_id
LEFT JOIN member_counts        AS mc ON mc.mess_id = me.mess_id
LEFT JOIN collected_this_month AS c  ON c.mess_id  = me.mess_id;


-- >>>>>>>>>> views/07_v_overdue_dues.sql
-- ====================================================================
-- v_overdue_dues
-- Rent that nobody has paid after the deadline (status = overdue),
-- with the member, seat and how many days late.
-- Used by: Manager "Members with dues" list and the admin report.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_overdue_dues AS
SELECT d.due_id,
       d.member_id,
       r.mess_id,
       m.full_name,
       m.phone,
       m.student_id,
       r.room_no,
       s.seat_label,
       d.due_month,
       d.amount,
       d.due_date,
       DATEDIFF(CURDATE(), d.due_date) AS days_late
FROM rent_dues AS d
JOIN mess_members AS m ON m.member_id = d.member_id
JOIN seats AS s ON s.seat_id = m.seat_id
JOIN rooms AS r ON r.room_id = s.room_id
WHERE d.status = 'overdue';


-- >>>>>>>>>> views/08_v_newsfeed.sql
-- ====================================================================
-- v_newsfeed
-- The newsfeed: vacancy posts (from managers) and seat wanted posts (from
-- students) in one list. UNION ALL puts the two kinds of rows under the
-- same columns. Removed posts are left out; the page sorts by created_at.
-- ====================================================================
USE mess_finder;

CREATE OR REPLACE VIEW v_newsfeed AS
SELECT 'vacancy'              AS post_type,
       vp.post_id             AS post_id,
       vp.created_at          AS created_at,
       vp.mess_id             AS mess_id,
       me.mess_name           AS author_name,
       me.manager_id          AS author_user_id,
       a.area_id              AS area_id,
       a.area_name            AS area_name,
       me.mess_type           AS mess_type,
       vp.title               AS title,
       vp.description         AS description,
       vp.available_from      AS date_from,
       CAST(NULL AS DECIMAL(10,2)) AS budget_min,
       CAST(NULL AS DECIMAL(10,2)) AS budget_max,
       vp.status              AS status,
       (SELECT COUNT(*) FROM post_comments AS pc
         WHERE pc.vacancy_post_id = vp.post_id AND pc.is_deleted = 0) AS comment_count,
       (SELECT COUNT(*) FROM interests AS i WHERE i.post_id = vp.post_id) AS interest_count
FROM vacancy_posts AS vp
JOIN messes AS me ON me.mess_id = vp.mess_id
JOIN areas  AS a  ON a.area_id  = me.area_id
WHERE vp.status <> 'removed'

UNION ALL

SELECT 'seat_wanted'          AS post_type,
       wp.wanted_id           AS post_id,
       wp.created_at          AS created_at,
       CAST(NULL AS SIGNED)   AS mess_id,
       u.full_name            AS author_name,
       wp.student_id          AS author_user_id,
       wp.area_id             AS area_id,
       a.area_name            AS area_name,
       wp.mess_type           AS mess_type,
       wp.title               AS title,
       wp.description         AS description,
       wp.needed_from         AS date_from,
       wp.budget_min          AS budget_min,
       wp.budget_max          AS budget_max,
       wp.status              AS status,
       (SELECT COUNT(*) FROM post_comments AS pc
         WHERE pc.wanted_post_id = wp.wanted_id AND pc.is_deleted = 0) AS comment_count,
       0                      AS interest_count
FROM seat_wanted_posts AS wp
JOIN users AS u ON u.user_id = wp.student_id
LEFT JOIN areas AS a ON a.area_id = wp.area_id
WHERE wp.status <> 'removed';


-- >>>>>>>>>> functions/01_fn_avg_rating.sql
-- ====================================================================
-- fn_avg_rating(mess_id)
-- Average overall rating of a mess, rounded to 2 decimals.
-- Returns NULL when the mess has no review yet.
-- ====================================================================
USE mess_finder;

DROP FUNCTION IF EXISTS fn_avg_rating;

DELIMITER $$
CREATE FUNCTION fn_avg_rating (p_mess_id INT)
RETURNS DECIMAL(3,2)
READS SQL DATA
BEGIN
    DECLARE v_avg DECIMAL(3,2);

    SELECT ROUND(AVG(rating), 2)
      INTO v_avg
      FROM reviews
     WHERE mess_id = p_mess_id;

    RETURN v_avg;
END$$
DELIMITER ;


-- >>>>>>>>>> functions/02_fn_available_seats.sql
-- ====================================================================
-- fn_available_seats(mess_id)
-- Number of free seats in a mess (inactive rooms and seats are not counted).
-- ====================================================================
USE mess_finder;

DROP FUNCTION IF EXISTS fn_available_seats;

DELIMITER $$
CREATE FUNCTION fn_available_seats (p_mess_id INT)
RETURNS INT
READS SQL DATA
BEGIN
    DECLARE v_free INT;

    SELECT COUNT(*)
      INTO v_free
      FROM seats AS s
      JOIN rooms AS r ON r.room_id = s.room_id
     WHERE r.mess_id = p_mess_id
       AND r.is_active = 1
       AND s.status = 'available';

    RETURN v_free;
END$$
DELIMITER ;


-- >>>>>>>>>> functions/03_fn_member_outstanding.sql
-- ====================================================================
-- fn_member_outstanding(member_id)
-- How much rent a member still owes: all dues minus the money paid for them.
-- Advance payments are not counted, they are not linked to a due.
-- ====================================================================
USE mess_finder;

DROP FUNCTION IF EXISTS fn_member_outstanding;

DELIMITER $$
CREATE FUNCTION fn_member_outstanding (p_member_id INT)
RETURNS DECIMAL(10,2)
READS SQL DATA
BEGIN
    DECLARE v_due  DECIMAL(10,2);
    DECLARE v_paid DECIMAL(10,2);

    SELECT COALESCE(SUM(amount), 0)
      INTO v_due
      FROM rent_dues
     WHERE member_id = p_member_id;

    SELECT COALESCE(SUM(amount), 0)
      INTO v_paid
      FROM payments
     WHERE member_id = p_member_id
       AND due_id IS NOT NULL;

    RETURN v_due - v_paid;
END$$
DELIMITER ;


-- >>>>>>>>>> functions/04_fn_distance_km.sql
-- ====================================================================
-- fn_distance_km(lat1, lng1, lat2, lng2)
-- Distance between two points on the earth in kilometres (Haversine formula).
-- Used by the "Nearby" search: messes within X km of a university.
-- ====================================================================
USE mess_finder;

DROP FUNCTION IF EXISTS fn_distance_km;

DELIMITER $$
CREATE FUNCTION fn_distance_km (
    p_lat1 DECIMAL(9,6), p_lng1 DECIMAL(9,6),
    p_lat2 DECIMAL(9,6), p_lng2 DECIMAL(9,6)
)
RETURNS DECIMAL(8,2)
DETERMINISTIC
NO SQL
BEGIN
    DECLARE v_earth_radius_km DOUBLE DEFAULT 6371;
    DECLARE v_a DOUBLE;

    -- a = sin^2(dLat/2) + cos(lat1) * cos(lat2) * sin^2(dLng/2)
    SET v_a = POW(SIN(RADIANS(p_lat2 - p_lat1) / 2), 2)
            + COS(RADIANS(p_lat1)) * COS(RADIANS(p_lat2))
            * POW(SIN(RADIANS(p_lng2 - p_lng1) / 2), 2);

    -- LEAST(1, ...) protects ASIN from tiny rounding errors above 1
    RETURN ROUND(2 * v_earth_radius_km * ASIN(LEAST(1, SQRT(v_a))), 2);
END$$
DELIMITER ;


-- >>>>>>>>>> functions/05_fn_first_due_date.sql
-- ====================================================================
-- fn_first_due_date(join_date)
-- Last day to pay the rent of the month a member joins.
-- Rule: the 10th of that month, but never earlier than 7 days after joining.
-- ====================================================================
USE mess_finder;

DROP FUNCTION IF EXISTS fn_first_due_date;

DELIMITER $$
CREATE FUNCTION fn_first_due_date (p_join_date DATE)
RETURNS DATE
DETERMINISTIC
NO SQL
BEGIN
    DECLARE v_tenth DATE;

    SET v_tenth = DATE_ADD(DATE_FORMAT(p_join_date, '%Y-%m-01'), INTERVAL 9 DAY);

    RETURN GREATEST(v_tenth, DATE_ADD(p_join_date, INTERVAL 7 DAY));
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/01_sp_add_member.sql
-- ====================================================================
-- sp_add_member
-- The manager gives a seat to a person. This is how a "booking" happens.
--
-- Everything runs in ONE transaction, so it either all happens or nothing does:
--   1. lock the seat row (two requests for the same seat wait for each other)
--   2. check the seat belongs to this manager and is free
--   3. add the member (a trigger then marks the seat as booked)
--   4. create the rent due of the joining month (full month rent)
--   5. record the advance payment, if there is one
-- If any step fails, ROLLBACK undoes the earlier steps.
--
-- When p_student_id is given, name, phone and gender are taken from the account.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_add_member;

DELIMITER $$
CREATE PROCEDURE sp_add_member (
    IN  p_manager_id      INT,
    IN  p_seat_id         INT,
    IN  p_student_id      INT,            -- NULL when the member has no account
    IN  p_full_name       VARCHAR(100),   -- can be NULL when p_student_id is given
    IN  p_phone           VARCHAR(20),    -- can be NULL when p_student_id is given
    IN  p_gender          VARCHAR(10),    -- 'male' or 'female', can be NULL when p_student_id is given
    IN  p_occupation      VARCHAR(100),
    IN  p_monthly_rent    DECIMAL(10,2),  -- NULL = use the current rent of the seat
    IN  p_advance_amount  DECIMAL(10,2),  -- agreed advance, received now. 0 = no advance
    IN  p_payment_method  VARCHAR(10),    -- 'cash', 'bkash' or 'nagad'
    IN  p_join_date       DATE,
    OUT p_member_id       INT
)
BEGIN
    DECLARE v_seat_manager INT;
    DECLARE v_mess_status  VARCHAR(20);
    DECLARE v_seat_status  VARCHAR(20);
    DECLARE v_seat_rent    DECIMAL(10,2);
    DECLARE v_name         VARCHAR(100);
    DECLARE v_phone        VARCHAR(20);
    DECLARE v_gender       VARCHAR(10);
    DECLARE v_rent         DECIMAL(10,2);
    DECLARE v_due_date     DATE;

    -- any error undoes everything and is sent back to the caller
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- step 1: lock the seat row until this transaction ends
    SELECT me.manager_id, me.status, s.status, s.monthly_rent
      INTO v_seat_manager, v_mess_status, v_seat_status, v_seat_rent
      FROM seats AS s
      JOIN rooms AS r   ON r.room_id  = s.room_id
      JOIN messes AS me ON me.mess_id = r.mess_id
     WHERE s.seat_id = p_seat_id
       FOR UPDATE OF s;

    -- step 2: checks
    IF v_seat_manager IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Seat not found';
    END IF;
    IF v_seat_manager <> p_manager_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This seat does not belong to your mess';
    END IF;
    IF v_mess_status <> 'verified' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Your mess is not verified yet';
    END IF;
    IF v_seat_status <> 'available' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This seat is not available';
    END IF;

    -- member details: from the student account if linked, otherwise from the parameters
    IF p_student_id IS NOT NULL THEN
        SELECT u.full_name, u.phone, sp.gender
          INTO v_name, v_phone, v_gender
          FROM users AS u
          JOIN student_profiles AS sp ON sp.student_id = u.user_id
         WHERE u.user_id = p_student_id
           AND u.is_active = 1;

        IF v_name IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Student account not found or blocked';
        END IF;
        SET v_name  = COALESCE(p_full_name, v_name);
        SET v_phone = COALESCE(p_phone, v_phone);
    ELSE
        IF p_full_name IS NULL OR p_phone IS NULL OR p_gender IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Name, phone and gender are required for a member without an account';
        END IF;
        SET v_name   = p_full_name;
        SET v_phone  = p_phone;
        SET v_gender = p_gender;
    END IF;

    SET v_rent = COALESCE(p_monthly_rent, v_seat_rent);

    -- step 3: add the member (triggers check the gender rule and mark the seat as booked)
    INSERT INTO mess_members
           (seat_id, student_id, full_name, phone, gender, occupation,
            monthly_rent, advance_amount, join_date, status)
    VALUES (p_seat_id, p_student_id, v_name, v_phone, v_gender, p_occupation,
            v_rent, COALESCE(p_advance_amount, 0), p_join_date, 'active');

    SET p_member_id = LAST_INSERT_ID();

    -- step 4: rent due of the joining month, full month rent
    SET v_due_date = fn_first_due_date(p_join_date);
    INSERT INTO rent_dues (member_id, due_month, amount, due_date, status)
    VALUES (p_member_id,
            DATE_FORMAT(p_join_date, '%Y-%m-01'),
            v_rent,
            v_due_date,
            IF(v_due_date < CURDATE(), 'overdue', 'due'));

    -- step 5: advance payment
    IF COALESCE(p_advance_amount, 0) > 0 THEN
        INSERT INTO payments (member_id, due_id, amount, payment_type, method, paid_at)
        VALUES (p_member_id, NULL, p_advance_amount, 'advance',
                COALESCE(p_payment_method, 'cash'), TIMESTAMP(p_join_date, CURTIME()));
    END IF;

    COMMIT;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/02_sp_mark_member_left.sql
-- ====================================================================
-- sp_mark_member_left
-- The manager says a member has left. The row stays (soft delete), only
-- status and leave_date change. A trigger then makes the seat free again.
-- Rent of the leaving month stays due in full; no new dues are made after that.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_mark_member_left;

DELIMITER $$
CREATE PROCEDURE sp_mark_member_left (
    IN p_manager_id  INT,
    IN p_member_id   INT,
    IN p_leave_date  DATE
)
BEGIN
    DECLARE v_manager_id INT;
    DECLARE v_status     VARCHAR(10);
    DECLARE v_join_date  DATE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- lock the member row so two clicks cannot change it twice
    SELECT me.manager_id, m.status, m.join_date
      INTO v_manager_id, v_status, v_join_date
      FROM mess_members AS m
      JOIN seats AS s   ON s.seat_id  = m.seat_id
      JOIN rooms AS r   ON r.room_id  = s.room_id
      JOIN messes AS me ON me.mess_id = r.mess_id
     WHERE m.member_id = p_member_id
       FOR UPDATE OF m;

    IF v_manager_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Member not found';
    END IF;
    IF v_manager_id <> p_manager_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This member does not belong to your mess';
    END IF;
    IF v_status <> 'active' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This member has already left';
    END IF;
    IF p_leave_date < v_join_date THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Leave date cannot be before the join date';
    END IF;

    UPDATE mess_members
       SET status = 'left',
           leave_date = p_leave_date
     WHERE member_id = p_member_id;

    COMMIT;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/03_sp_record_payment.sql
-- ====================================================================
-- sp_record_payment
-- The manager records money received from a member.
--   monthly payment: p_due_id is the due it pays (can be a part of it)
--   advance payment: p_due_id is NULL
-- The due row is locked first, so two payments for the same due are counted
-- one after another. A trigger blocks paying more than the due and updates
-- the due status to partial or paid.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_record_payment;

DELIMITER $$
CREATE PROCEDURE sp_record_payment (
    IN  p_manager_id  INT,
    IN  p_member_id   INT,
    IN  p_due_id      INT,            -- NULL for an advance payment
    IN  p_amount      DECIMAL(10,2),
    IN  p_method      VARCHAR(10),    -- 'cash', 'bkash' or 'nagad'
    IN  p_paid_at     DATETIME,       -- NULL = now
    OUT p_payment_id  INT
)
BEGIN
    DECLARE v_manager_id INT;
    DECLARE v_due_member INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- the member must belong to this manager's mess
    SELECT me.manager_id
      INTO v_manager_id
      FROM mess_members AS m
      JOIN seats AS s   ON s.seat_id  = m.seat_id
      JOIN rooms AS r   ON r.room_id  = s.room_id
      JOIN messes AS me ON me.mess_id = r.mess_id
     WHERE m.member_id = p_member_id;

    IF v_manager_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Member not found';
    END IF;
    IF v_manager_id <> p_manager_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This member does not belong to your mess';
    END IF;

    IF p_due_id IS NOT NULL THEN
        -- lock the due, then check it is really this member's due
        SELECT member_id
          INTO v_due_member
          FROM rent_dues
         WHERE due_id = p_due_id
           FOR UPDATE;

        IF v_due_member IS NULL OR v_due_member <> p_member_id THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This due does not belong to the member';
        END IF;
    END IF;

    INSERT INTO payments (member_id, due_id, amount, payment_type, method, paid_at)
    VALUES (p_member_id,
            p_due_id,
            p_amount,
            IF(p_due_id IS NULL, 'advance', 'monthly'),
            p_method,
            COALESCE(p_paid_at, NOW()));

    SET p_payment_id = LAST_INSERT_ID();

    COMMIT;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/04_sp_generate_monthly_dues.sql
-- ====================================================================
-- sp_generate_monthly_dues
-- Creates the rent due of one month for every member who has to pay it.
-- A CURSOR walks through the members one by one.
-- Members who already have a due for that month are skipped, so it is safe
-- to run the procedure twice.
-- Called by the event ev_create_monthly_dues on the 1st of every month.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_generate_monthly_dues;

DELIMITER $$
CREATE PROCEDURE sp_generate_monthly_dues (
    IN  p_month    DATE,   -- any day of the month
    OUT p_created  INT     -- how many dues were created
)
BEGIN
    DECLARE v_month_start DATE;
    DECLARE v_due_date    DATE;
    DECLARE v_member_id   INT;
    DECLARE v_rent        DECIMAL(10,2);
    DECLARE v_done        TINYINT DEFAULT 0;

    -- members who joined before the end of the month, are still active (or left during
    -- the month), and do not have a due for the month yet
    DECLARE cur_members CURSOR FOR
        SELECT m.member_id, m.monthly_rent
          FROM mess_members AS m
         WHERE m.join_date <= LAST_DAY(v_month_start)
           AND (m.status = 'active' OR m.leave_date >= v_month_start)
           AND NOT EXISTS (SELECT 1
                             FROM rent_dues AS d
                            WHERE d.member_id = m.member_id
                              AND d.due_month = v_month_start);

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SET v_month_start = DATE_FORMAT(p_month, '%Y-%m-01');
    SET v_due_date    = DATE_ADD(v_month_start, INTERVAL 9 DAY);   -- the 10th
    SET p_created     = 0;

    OPEN cur_members;

    member_loop: LOOP
        FETCH cur_members INTO v_member_id, v_rent;
        IF v_done = 1 THEN
            LEAVE member_loop;
        END IF;

        INSERT INTO rent_dues (member_id, due_month, amount, due_date, status)
        VALUES (v_member_id, v_month_start, v_rent, v_due_date,
                IF(v_due_date < CURDATE(), 'overdue', 'due'));

        SET p_created = p_created + 1;
    END LOOP;

    CLOSE cur_members;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/05_sp_process_overdue_dues.sql
-- ====================================================================
-- sp_process_overdue_dues
-- Finds dues where nothing was paid and the deadline has passed, marks them
-- as overdue, and sends a notification to the member (if linked to an
-- account) and to the manager. A CURSOR handles the dues one by one.
-- A due that was partly paid stays "partial" (the manager still sees the rest).
-- Called by the event ev_process_overdue_dues every day.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_process_overdue_dues;

DELIMITER $$
CREATE PROCEDURE sp_process_overdue_dues (
    OUT p_marked INT    -- how many dues were marked overdue
)
BEGIN
    DECLARE v_due_id     INT;
    DECLARE v_month_text VARCHAR(20);
    DECLARE v_member     VARCHAR(100);
    DECLARE v_student_id INT;
    DECLARE v_manager_id INT;
    DECLARE v_done       TINYINT DEFAULT 0;

    DECLARE cur_dues CURSOR FOR
        SELECT d.due_id,
               DATE_FORMAT(d.due_month, '%M %Y'),
               m.full_name,
               m.student_id,
               me.manager_id
          FROM rent_dues AS d
          JOIN mess_members AS m ON m.member_id = d.member_id
          JOIN seats AS s        ON s.seat_id   = m.seat_id
          JOIN rooms AS r        ON r.room_id   = s.room_id
          JOIN messes AS me      ON me.mess_id  = r.mess_id
         WHERE d.status = 'due'
           AND d.due_date < CURDATE();

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SET p_marked = 0;

    OPEN cur_dues;

    due_loop: LOOP
        FETCH cur_dues INTO v_due_id, v_month_text, v_member, v_student_id, v_manager_id;
        IF v_done = 1 THEN
            LEAVE due_loop;
        END IF;

        UPDATE rent_dues SET status = 'overdue' WHERE due_id = v_due_id;

        IF v_student_id IS NOT NULL THEN
            INSERT INTO notifications (user_id, message)
            VALUES (v_student_id, CONCAT('Your rent for ', v_month_text, ' is overdue.'));
        END IF;

        INSERT INTO notifications (user_id, message)
        VALUES (v_manager_id, CONCAT('Overdue rent: ', v_member, ' (', v_month_text, ').'));

        SET p_marked = p_marked + 1;
    END LOOP;

    CLOSE cur_dues;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/06_sp_expire_old_posts.sql
-- ====================================================================
-- sp_expire_old_posts
-- Open posts older than 30 days become "expired". After that nobody can
-- comment on them. Called by the event ev_expire_old_posts every day.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_expire_old_posts;

DELIMITER $$
CREATE PROCEDURE sp_expire_old_posts (
    OUT p_vacancy_posts  INT,
    OUT p_wanted_posts   INT
)
BEGIN
    UPDATE vacancy_posts
       SET status = 'expired'
     WHERE status = 'open'
       AND created_at < DATE_SUB(NOW(), INTERVAL 30 DAY);
    SET p_vacancy_posts = ROW_COUNT();

    UPDATE seat_wanted_posts
       SET status = 'expired'
     WHERE status = 'open'
       AND created_at < DATE_SUB(NOW(), INTERVAL 30 DAY);
    SET p_wanted_posts = ROW_COUNT();
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/07_sp_toggle_interest.sql
-- ====================================================================
-- sp_toggle_interest
-- The Interested button. First press adds the mess to the student's
-- Interested list, second press removes it.
-- The row is deleted first: if a row was deleted, the student pressed it
-- again; if nothing was deleted, the row is new.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_toggle_interest;

DELIMITER $$
CREATE PROCEDURE sp_toggle_interest (
    IN  p_student_id     INT,
    IN  p_mess_id        INT,
    IN  p_post_id        INT,       -- post the button was pressed on, NULL if pressed on the mess page
    OUT p_is_interested  TINYINT    -- 1 = now interested, 0 = removed
)
BEGIN
    -- two quick double clicks can try to add the same row twice, treat that as "interested"
    DECLARE CONTINUE HANDLER FOR 1062 SET p_is_interested = 1;

    DELETE FROM interests
     WHERE student_id = p_student_id
       AND mess_id = p_mess_id;

    IF ROW_COUNT() > 0 THEN
        SET p_is_interested = 0;
    ELSE
        INSERT INTO interests (student_id, mess_id, post_id)
        VALUES (p_student_id, p_mess_id, p_post_id);
        SET p_is_interested = 1;
    END IF;
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/08_sp_get_or_create_conversation.sql
-- ====================================================================
-- sp_get_or_create_conversation
-- Opens the chat between a student and a mess. If the chat already exists
-- its id is returned, otherwise a new chat is created.
-- It uses INSERT ... ON DUPLICATE KEY UPDATE: the UNIQUE key (mess_id, student_id)
-- decides if the row exists, so two people clicking Chat at the same time
-- still end up with one conversation.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_get_or_create_conversation;

DELIMITER $$
CREATE PROCEDURE sp_get_or_create_conversation (
    IN  p_mess_id          INT,
    IN  p_student_id       INT,
    OUT p_conversation_id  INT
)
BEGIN
    INSERT INTO conversations (mess_id, student_id)
    VALUES (p_mess_id, p_student_id)
    ON DUPLICATE KEY UPDATE conversation_id = LAST_INSERT_ID(conversation_id);

    -- LAST_INSERT_ID() is the new id, or the old id that was set in the UPDATE part above
    SET p_conversation_id = LAST_INSERT_ID();
END$$
DELIMITER ;


-- >>>>>>>>>> procedures/09_sp_create_vacancy_post.sql
-- ====================================================================
-- sp_create_vacancy_post
-- A manager posts free seats on the newsfeed.
-- The seats come as a JSON list, for example [3, 5, 8]. JSON_TABLE turns the
-- list into rows so all the seats can be saved with one INSERT.
-- The post and its seats are saved in one transaction.
-- Triggers check that the mess is verified and every seat is a free seat of
-- this mess.
-- ====================================================================
USE mess_finder;

DROP PROCEDURE IF EXISTS sp_create_vacancy_post;

DELIMITER $$
CREATE PROCEDURE sp_create_vacancy_post (
    IN  p_manager_id      INT,
    IN  p_title           VARCHAR(150),
    IN  p_description     TEXT,
    IN  p_available_from  DATE,
    IN  p_seat_ids        JSON,       -- for example '[3, 5, 8]'
    OUT p_post_id         INT
)
BEGIN
    DECLARE v_mess_id INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_seat_ids IS NULL OR JSON_LENGTH(p_seat_ids) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Choose at least one seat for the post';
    END IF;

    SELECT mess_id INTO v_mess_id FROM messes WHERE manager_id = p_manager_id;
    IF v_mess_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Create your mess before posting';
    END IF;

    START TRANSACTION;

    INSERT INTO vacancy_posts (mess_id, title, description, available_from)
    VALUES (v_mess_id, p_title, p_description, p_available_from);

    SET p_post_id = LAST_INSERT_ID();

    INSERT INTO post_seats (post_id, seat_id)
    SELECT p_post_id, jt.seat_id
      FROM JSON_TABLE(p_seat_ids, '$[*]' COLUMNS (seat_id INT PATH '$')) AS jt;

    COMMIT;
END$$
DELIMITER ;


-- >>>>>>>>>> indexes/01_extra_indexes.sql
-- ====================================================================
-- Extra indexes for the queries the website runs most often.
-- (Primary keys, unique keys and foreign keys already have an index;
--  the tables in schema/ also have a few. These are the ones added on top.)
-- Run indexes/ after seed/, the tables must exist.
-- queries/advanced/09_index_explain_demo.sql shows what an index does with EXPLAIN.
-- ====================================================================
USE mess_finder;

-- Seat counts per room and status (free seats on every mess card)
ALTER TABLE seats
    ADD INDEX idx_seats_room_status (room_id, status);

-- The daily overdue job looks for dues by status and deadline
ALTER TABLE rent_dues
    ADD INDEX idx_rent_dues_status_due_date (status, due_date);

-- Payment history of one member, newest first
ALTER TABLE payments
    ADD INDEX idx_payments_member_paid_at (member_id, paid_at);

-- Newsfeed: open posts, newest first
ALTER TABLE vacancy_posts
    ADD INDEX idx_vacancy_posts_status_created (status, created_at);

ALTER TABLE seat_wanted_posts
    ADD INDEX idx_wanted_posts_status_created (status, created_at);

-- Manager's visit request list
ALTER TABLE visit_requests
    ADD INDEX idx_visit_requests_mess_status_time (mess_id, status, visit_time);

-- Find the members who are still active or already left, by join date
ALTER TABLE mess_members
    ADD INDEX idx_mess_members_status_join_date (status, join_date);


-- >>>>>>>>>> triggers/01_trg_mess_members.sql
-- ====================================================================
-- Triggers of mess_members
--
-- BEFORE triggers refuse wrong data (cross-table rules a CHECK cannot do):
--   * gender must match the mess type (boys mess: male, girls mess: female)
--   * a linked member must have the same gender as the student account
--   * a member can be added only to a free seat
-- AFTER triggers keep other tables in step:
--   * member added   -> seat becomes booked, the student gets a notification
--   * member left    -> seat becomes free again, the student gets a notification
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_mess_members_before_insert;
DROP TRIGGER IF EXISTS trg_mess_members_before_update;
DROP TRIGGER IF EXISTS trg_mess_members_after_insert;
DROP TRIGGER IF EXISTS trg_mess_members_after_update;

DELIMITER $$

CREATE TRIGGER trg_mess_members_before_insert
BEFORE INSERT ON mess_members
FOR EACH ROW
BEGIN
    DECLARE v_mess_type      VARCHAR(10);
    DECLARE v_seat_status    VARCHAR(20);
    DECLARE v_student_gender VARCHAR(10);

    SELECT me.mess_type, s.status
      INTO v_mess_type, v_seat_status
      FROM seats AS s
      JOIN rooms AS r   ON r.room_id  = s.room_id
      JOIN messes AS me ON me.mess_id = r.mess_id
     WHERE s.seat_id = NEW.seat_id;

    IF (v_mess_type = 'boys' AND NEW.gender <> 'male')
       OR (v_mess_type = 'girls' AND NEW.gender <> 'female') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Gender does not match the mess type';
    END IF;

    IF NEW.student_id IS NOT NULL THEN
        SELECT gender INTO v_student_gender
          FROM student_profiles
         WHERE student_id = NEW.student_id;

        IF v_student_gender <> NEW.gender THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Member gender does not match the student account';
        END IF;
    END IF;

    IF NEW.status = 'active' AND v_seat_status <> 'available' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This seat is not available';
    END IF;
END$$


CREATE TRIGGER trg_mess_members_before_update
BEFORE UPDATE ON mess_members
FOR EACH ROW
BEGIN
    DECLARE v_mess_type      VARCHAR(10);
    DECLARE v_student_gender VARCHAR(10);

    IF NEW.seat_id <> OLD.seat_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The seat of a member cannot be changed';
    END IF;

    IF OLD.status = 'left' AND NEW.status = 'active' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A member who left cannot be activated again, add a new member';
    END IF;

    -- check the gender rules again only if something they depend on changed
    IF NEW.gender <> OLD.gender OR NOT (NEW.student_id <=> OLD.student_id) THEN
        SELECT me.mess_type
          INTO v_mess_type
          FROM seats AS s
          JOIN rooms AS r   ON r.room_id  = s.room_id
          JOIN messes AS me ON me.mess_id = r.mess_id
         WHERE s.seat_id = NEW.seat_id;

        IF (v_mess_type = 'boys' AND NEW.gender <> 'male')
           OR (v_mess_type = 'girls' AND NEW.gender <> 'female') THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Gender does not match the mess type';
        END IF;

        IF NEW.student_id IS NOT NULL THEN
            SELECT gender INTO v_student_gender
              FROM student_profiles
             WHERE student_id = NEW.student_id;

            IF v_student_gender <> NEW.gender THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Member gender does not match the student account';
            END IF;
        END IF;
    END IF;
END$$


CREATE TRIGGER trg_mess_members_after_insert
AFTER INSERT ON mess_members
FOR EACH ROW
BEGIN
    DECLARE v_mess_name  VARCHAR(120);
    DECLARE v_room_no    VARCHAR(10);
    DECLARE v_seat_label VARCHAR(10);

    IF NEW.status = 'active' THEN
        UPDATE seats SET status = 'booked' WHERE seat_id = NEW.seat_id;

        IF NEW.student_id IS NOT NULL THEN
            SELECT me.mess_name, r.room_no, s.seat_label
              INTO v_mess_name, v_room_no, v_seat_label
              FROM seats AS s
              JOIN rooms AS r   ON r.room_id  = s.room_id
              JOIN messes AS me ON me.mess_id = r.mess_id
             WHERE s.seat_id = NEW.seat_id;

            INSERT INTO notifications (user_id, message)
            VALUES (NEW.student_id,
                    CONCAT('You were added to ', v_mess_name, ' (room ', v_room_no, ', seat ', v_seat_label, ').'));
        END IF;
    END IF;
END$$


CREATE TRIGGER trg_mess_members_after_update
AFTER UPDATE ON mess_members
FOR EACH ROW
BEGIN
    DECLARE v_mess_name VARCHAR(120);

    IF OLD.status = 'active' AND NEW.status = 'left' THEN
        -- the seat is free again (an inactive seat stays inactive)
        UPDATE seats
           SET status = 'available'
         WHERE seat_id = NEW.seat_id
           AND status = 'booked';

        IF NEW.student_id IS NOT NULL THEN
            SELECT me.mess_name
              INTO v_mess_name
              FROM seats AS s
              JOIN rooms AS r   ON r.room_id  = s.room_id
              JOIN messes AS me ON me.mess_id = r.mess_id
             WHERE s.seat_id = NEW.seat_id;

            INSERT INTO notifications (user_id, message)
            VALUES (NEW.student_id,
                    CONCAT('You were marked as left from ', v_mess_name, ' on ',
                           DATE_FORMAT(NEW.leave_date, '%e %b %Y'), '.'));
        END IF;
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/02_trg_seats.sql
-- ====================================================================
-- Triggers of seats
--
-- BEFORE UPDATE: a seat that has an active member cannot become inactive or free by hand.
-- AFTER UPDATE:
--   * rent changed   -> the old and new rent are saved in seat_rent_log
--   * seat not free anymore -> vacancy posts that have no free seat left are closed
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_seats_before_update;
DROP TRIGGER IF EXISTS trg_seats_after_update;

DELIMITER $$

CREATE TRIGGER trg_seats_before_update
BEFORE UPDATE ON seats
FOR EACH ROW
BEGIN
    IF OLD.status = 'booked' AND NEW.status IN ('available', 'inactive') THEN
        -- allowed only when nobody lives in the seat any more
        IF EXISTS (SELECT 1 FROM mess_members WHERE seat_id = NEW.seat_id AND status = 'active') THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This seat has an active member';
        END IF;
    END IF;
END$$


CREATE TRIGGER trg_seats_after_update
AFTER UPDATE ON seats
FOR EACH ROW
BEGIN
    IF OLD.monthly_rent <> NEW.monthly_rent THEN
        INSERT INTO seat_rent_log (seat_id, old_rent, new_rent)
        VALUES (NEW.seat_id, OLD.monthly_rent, NEW.monthly_rent);
    END IF;

    IF OLD.status = 'available' AND NEW.status <> 'available' THEN
        -- close the open posts of this seat that now have no free seat at all
        UPDATE vacancy_posts AS vp
           SET vp.status = 'closed'
         WHERE vp.status = 'open'
           AND vp.post_id IN (SELECT ps.post_id FROM post_seats AS ps WHERE ps.seat_id = NEW.seat_id)
           AND NOT EXISTS (SELECT 1
                             FROM post_seats AS ps2
                             JOIN seats AS s2 ON s2.seat_id = ps2.seat_id
                            WHERE ps2.post_id = vp.post_id
                              AND s2.status = 'available');
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/03_trg_payments.sql
-- ====================================================================
-- Triggers of payments
--
-- BEFORE INSERT: the money paid for a due can never be more than the due.
-- AFTER INSERT:
--   * the due becomes partial (some paid) or paid (all paid)
--   * the student (if the member has an account) gets a notification
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_payments_before_insert;
DROP TRIGGER IF EXISTS trg_payments_after_insert;

DELIMITER $$

CREATE TRIGGER trg_payments_before_insert
BEFORE INSERT ON payments
FOR EACH ROW
BEGIN
    DECLARE v_due_amount DECIMAL(10,2);
    DECLARE v_paid_so_far DECIMAL(10,2);

    IF NEW.due_id IS NOT NULL THEN
        SELECT amount INTO v_due_amount FROM rent_dues WHERE due_id = NEW.due_id;

        SELECT COALESCE(SUM(amount), 0)
          INTO v_paid_so_far
          FROM payments
         WHERE due_id = NEW.due_id;

        IF v_paid_so_far + NEW.amount > v_due_amount THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payment is more than the remaining due';
        END IF;
    END IF;
END$$


CREATE TRIGGER trg_payments_after_insert
AFTER INSERT ON payments
FOR EACH ROW
BEGIN
    DECLARE v_due_amount DECIMAL(10,2);
    DECLARE v_paid       DECIMAL(10,2);
    DECLARE v_student_id INT;

    IF NEW.due_id IS NOT NULL THEN
        SELECT amount INTO v_due_amount FROM rent_dues WHERE due_id = NEW.due_id;
        SELECT SUM(amount) INTO v_paid FROM payments WHERE due_id = NEW.due_id;

        UPDATE rent_dues
           SET status = CASE
                            WHEN v_paid >= v_due_amount THEN 'paid'
                            WHEN v_paid > 0             THEN 'partial'
                            ELSE status
                        END
         WHERE due_id = NEW.due_id;
    END IF;

    SELECT student_id INTO v_student_id FROM mess_members WHERE member_id = NEW.member_id;

    IF v_student_id IS NOT NULL THEN
        INSERT INTO notifications (user_id, message)
        VALUES (v_student_id,
                CONCAT('Payment of ', FORMAT(NEW.amount, 0), ' BDT received (', NEW.payment_type, ').'));
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/04_trg_reviews.sql
-- ====================================================================
-- Triggers of reviews
--
-- BEFORE INSERT: only a person who lived in the mess (current or ex member
--                with a linked account) can write a review for it.
-- AFTER INSERT:  the manager gets a notification.
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_reviews_before_insert;
DROP TRIGGER IF EXISTS trg_reviews_after_insert;

DELIMITER $$

CREATE TRIGGER trg_reviews_before_insert
BEFORE INSERT ON reviews
FOR EACH ROW
BEGIN
    IF NOT EXISTS (SELECT 1
                     FROM mess_members AS m
                     JOIN seats AS s ON s.seat_id = m.seat_id
                     JOIN rooms AS r ON r.room_id = s.room_id
                    WHERE m.student_id = NEW.student_id
                      AND r.mess_id = NEW.mess_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only current or past members of this mess can write a review';
    END IF;
END$$


CREATE TRIGGER trg_reviews_after_insert
AFTER INSERT ON reviews
FOR EACH ROW
BEGIN
    DECLARE v_manager_id INT;
    DECLARE v_student    VARCHAR(100);

    SELECT manager_id INTO v_manager_id FROM messes WHERE mess_id = NEW.mess_id;
    SELECT full_name  INTO v_student    FROM users  WHERE user_id = NEW.student_id;

    INSERT INTO notifications (user_id, message)
    VALUES (v_manager_id, CONCAT('New review from ', v_student, ': ', NEW.rating, ' out of 5.'));
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/05_trg_messages.sql
-- ====================================================================
-- Triggers of messages (chat)
--
-- BEFORE INSERT: the sender must be one of the two people of the chat:
--                the student, or the manager of the mess.
-- AFTER INSERT:
--   * conversations.last_message_at is updated (the inbox is sorted by it)
--   * the other person gets a notification. If an unread notification of
--     the same kind is already waiting, no second one is made.
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_messages_before_insert;
DROP TRIGGER IF EXISTS trg_messages_after_insert;

DELIMITER $$

CREATE TRIGGER trg_messages_before_insert
BEFORE INSERT ON messages
FOR EACH ROW
BEGIN
    DECLARE v_student_id INT;
    DECLARE v_manager_id INT;

    SELECT c.student_id, me.manager_id
      INTO v_student_id, v_manager_id
      FROM conversations AS c
      JOIN messes AS me ON me.mess_id = c.mess_id
     WHERE c.conversation_id = NEW.conversation_id;

    IF NEW.sender_id <> v_student_id AND NEW.sender_id <> v_manager_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sender is not part of this conversation';
    END IF;
END$$


CREATE TRIGGER trg_messages_after_insert
AFTER INSERT ON messages
FOR EACH ROW
BEGIN
    DECLARE v_student_id INT;
    DECLARE v_manager_id INT;
    DECLARE v_receiver   INT;
    DECLARE v_sender     VARCHAR(100);
    DECLARE v_text       VARCHAR(255);

    UPDATE conversations
       SET last_message_at = NEW.sent_at
     WHERE conversation_id = NEW.conversation_id;

    SELECT c.student_id, me.manager_id
      INTO v_student_id, v_manager_id
      FROM conversations AS c
      JOIN messes AS me ON me.mess_id = c.mess_id
     WHERE c.conversation_id = NEW.conversation_id;

    SET v_receiver = IF(NEW.sender_id = v_student_id, v_manager_id, v_student_id);
    SELECT full_name INTO v_sender FROM users WHERE user_id = NEW.sender_id;
    SET v_text = CONCAT('New message from ', v_sender, '.');

    IF NOT EXISTS (SELECT 1 FROM notifications
                    WHERE user_id = v_receiver AND is_read = 0 AND message = v_text) THEN
        INSERT INTO notifications (user_id, message) VALUES (v_receiver, v_text);
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/06_trg_posts_and_interests.sql
-- ====================================================================
-- Triggers of the newsfeed: vacancy_posts, post_seats, interests, post_comments
--
--   * a vacancy post can be made only by a verified mess
--   * a post can advertise only free seats of its own mess
--   * Interested can be pressed only on a verified mess; the manager is told
--   * comments are closed on expired or removed posts; the owner of the post
--     is told about every new comment
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_vacancy_posts_before_insert;
DROP TRIGGER IF EXISTS trg_post_seats_before_insert;
DROP TRIGGER IF EXISTS trg_interests_before_insert;
DROP TRIGGER IF EXISTS trg_interests_after_insert;
DROP TRIGGER IF EXISTS trg_post_comments_before_insert;
DROP TRIGGER IF EXISTS trg_post_comments_after_insert;

DELIMITER $$

CREATE TRIGGER trg_vacancy_posts_before_insert
BEFORE INSERT ON vacancy_posts
FOR EACH ROW
BEGIN
    DECLARE v_status VARCHAR(20);

    SELECT status INTO v_status FROM messes WHERE mess_id = NEW.mess_id;
    IF v_status <> 'verified' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a verified mess can make a post';
    END IF;
END$$


CREATE TRIGGER trg_post_seats_before_insert
BEFORE INSERT ON post_seats
FOR EACH ROW
BEGIN
    DECLARE v_post_mess INT;
    DECLARE v_seat_mess INT;
    DECLARE v_seat_status VARCHAR(20);

    SELECT mess_id INTO v_post_mess FROM vacancy_posts WHERE post_id = NEW.post_id;

    SELECT r.mess_id, s.status
      INTO v_seat_mess, v_seat_status
      FROM seats AS s
      JOIN rooms AS r ON r.room_id = s.room_id
     WHERE s.seat_id = NEW.seat_id;

    IF v_seat_mess <> v_post_mess THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This seat belongs to another mess';
    END IF;
    IF v_seat_status <> 'available' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only free seats can be posted';
    END IF;
END$$


CREATE TRIGGER trg_interests_before_insert
BEFORE INSERT ON interests
FOR EACH ROW
BEGIN
    DECLARE v_status VARCHAR(20);

    SELECT status INTO v_status FROM messes WHERE mess_id = NEW.mess_id;
    IF v_status <> 'verified' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a verified mess can be marked as Interested';
    END IF;
END$$


CREATE TRIGGER trg_interests_after_insert
AFTER INSERT ON interests
FOR EACH ROW
BEGIN
    DECLARE v_manager_id INT;
    DECLARE v_student    VARCHAR(100);
    DECLARE v_mess_name  VARCHAR(120);

    SELECT manager_id, mess_name INTO v_manager_id, v_mess_name FROM messes WHERE mess_id = NEW.mess_id;
    SELECT full_name INTO v_student FROM users WHERE user_id = NEW.student_id;

    INSERT INTO notifications (user_id, message)
    VALUES (v_manager_id, CONCAT(v_student, ' is interested in ', v_mess_name, '.'));
END$$


CREATE TRIGGER trg_post_comments_before_insert
BEFORE INSERT ON post_comments
FOR EACH ROW
BEGIN
    DECLARE v_status VARCHAR(20);

    IF NEW.vacancy_post_id IS NOT NULL THEN
        SELECT status INTO v_status FROM vacancy_posts WHERE post_id = NEW.vacancy_post_id;
    ELSEIF NEW.wanted_post_id IS NOT NULL THEN
        SELECT status INTO v_status FROM seat_wanted_posts WHERE wanted_id = NEW.wanted_post_id;
    END IF;

    IF v_status IN ('expired', 'removed') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Comments are closed for this post';
    END IF;
END$$


CREATE TRIGGER trg_post_comments_after_insert
AFTER INSERT ON post_comments
FOR EACH ROW
BEGIN
    DECLARE v_owner INT;

    -- the owner of a vacancy post is the manager of the mess; of a seat wanted post, the student
    IF NEW.vacancy_post_id IS NOT NULL THEN
        SELECT me.manager_id
          INTO v_owner
          FROM vacancy_posts AS vp
          JOIN messes AS me ON me.mess_id = vp.mess_id
         WHERE vp.post_id = NEW.vacancy_post_id;
    ELSE
        SELECT student_id INTO v_owner FROM seat_wanted_posts WHERE wanted_id = NEW.wanted_post_id;
    END IF;

    IF v_owner IS NOT NULL AND v_owner <> NEW.user_id THEN
        INSERT INTO notifications (user_id, message)
        VALUES (v_owner, CONCAT('New comment on your post: ', LEFT(NEW.body, 80)));
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> triggers/07_trg_visits_complaints_messes.sql
-- ====================================================================
-- Triggers of visit_requests, complaints and messes
--
--   * visit request: the visit time must be in the future; the manager is
--     told about a new request; the student is told when it is confirmed or rejected
--   * complaint: every admin is told about a new complaint; the person who
--     complained is told when the status changes
--   * mess: the admins are told about a new mess; the manager is told when
--     the status of the mess changes (verified, suspended, closed)
-- ====================================================================
USE mess_finder;

DROP TRIGGER IF EXISTS trg_visit_requests_before_insert;
DROP TRIGGER IF EXISTS trg_visit_requests_after_insert;
DROP TRIGGER IF EXISTS trg_visit_requests_after_update;
DROP TRIGGER IF EXISTS trg_complaints_after_insert;
DROP TRIGGER IF EXISTS trg_complaints_after_update;
DROP TRIGGER IF EXISTS trg_messes_after_insert;
DROP TRIGGER IF EXISTS trg_messes_after_update;

DELIMITER $$

CREATE TRIGGER trg_visit_requests_before_insert
BEFORE INSERT ON visit_requests
FOR EACH ROW
BEGIN
    DECLARE v_status VARCHAR(20);

    SELECT status INTO v_status FROM messes WHERE mess_id = NEW.mess_id;
    IF v_status <> 'verified' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a verified mess can be visited';
    END IF;
    IF NEW.visit_time <= NOW() THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Visit time must be in the future';
    END IF;
END$$


CREATE TRIGGER trg_visit_requests_after_insert
AFTER INSERT ON visit_requests
FOR EACH ROW
BEGIN
    DECLARE v_manager_id INT;
    DECLARE v_student    VARCHAR(100);

    SELECT manager_id INTO v_manager_id FROM messes WHERE mess_id = NEW.mess_id;
    SELECT full_name  INTO v_student    FROM users  WHERE user_id = NEW.student_id;

    INSERT INTO notifications (user_id, message)
    VALUES (v_manager_id,
            CONCAT(v_student, ' requested a visit on ', DATE_FORMAT(NEW.visit_time, '%e %b, %l:%i %p'), '.'));
END$$


CREATE TRIGGER trg_visit_requests_after_update
AFTER UPDATE ON visit_requests
FOR EACH ROW
BEGIN
    DECLARE v_mess_name VARCHAR(120);

    IF OLD.status <> NEW.status AND NEW.status IN ('confirmed', 'rejected') THEN
        SELECT mess_name INTO v_mess_name FROM messes WHERE mess_id = NEW.mess_id;

        INSERT INTO notifications (user_id, message)
        VALUES (NEW.student_id,
                CONCAT('Your visit to ', v_mess_name, ' was ', NEW.status, ' (',
                       DATE_FORMAT(NEW.visit_time, '%e %b, %l:%i %p'), ').'));
    END IF;
END$$


CREATE TRIGGER trg_complaints_after_insert
AFTER INSERT ON complaints
FOR EACH ROW
BEGIN
    INSERT INTO notifications (user_id, message)
    SELECT user_id, CONCAT('New complaint: ', NEW.subject)
      FROM users
     WHERE role = 'admin' AND is_active = 1;
END$$


CREATE TRIGGER trg_complaints_after_update
AFTER UPDATE ON complaints
FOR EACH ROW
BEGIN
    IF OLD.status <> NEW.status THEN
        INSERT INTO notifications (user_id, message)
        VALUES (NEW.complainant_id,
                CONCAT('Your complaint "', NEW.subject, '" is now ', REPLACE(NEW.status, '_', ' '), '.'));
    END IF;
END$$


CREATE TRIGGER trg_messes_after_insert
AFTER INSERT ON messes
FOR EACH ROW
BEGIN
    IF NEW.status = 'pending' THEN
        INSERT INTO notifications (user_id, message)
        SELECT user_id, CONCAT('New mess waiting for verification: ', NEW.mess_name, '.')
          FROM users
         WHERE role = 'admin' AND is_active = 1;
    END IF;
END$$


CREATE TRIGGER trg_messes_after_update
AFTER UPDATE ON messes
FOR EACH ROW
BEGIN
    IF OLD.status <> NEW.status THEN
        INSERT INTO notifications (user_id, message)
        VALUES (NEW.manager_id,
                CONCAT('Your mess ', NEW.mess_name, ' is now ', NEW.status, '.'));
    END IF;
END$$

DELIMITER ;


-- >>>>>>>>>> events/01_ev_create_monthly_dues.sql
-- ====================================================================
-- ev_create_monthly_dues
-- Runs once a month, a few minutes after midnight on the 1st, and creates
-- the rent due of the new month for every member.
-- (The MySQL event scheduler must be ON. It is ON by default in MySQL 8.
--  Check with: SHOW VARIABLES LIKE 'event_scheduler';)
-- ====================================================================
USE mess_finder;

DROP EVENT IF EXISTS ev_create_monthly_dues;

DELIMITER $$
CREATE EVENT ev_create_monthly_dues
    ON SCHEDULE EVERY 1 MONTH
    STARTS TIMESTAMP(DATE_ADD(LAST_DAY(CURDATE()), INTERVAL 1 DAY), '00:05:00')
    ON COMPLETION PRESERVE
    ENABLE
    COMMENT 'Creates the rent due of the new month for every member'
DO
BEGIN
    CALL sp_generate_monthly_dues(CURDATE(), @dues_created);
END$$
DELIMITER ;


-- >>>>>>>>>> events/02_ev_process_overdue_dues.sql
-- ====================================================================
-- ev_process_overdue_dues
-- Runs every day after midnight. Marks unpaid dues whose deadline has
-- passed as overdue and sends the notifications.
-- ====================================================================
USE mess_finder;

DROP EVENT IF EXISTS ev_process_overdue_dues;

DELIMITER $$
CREATE EVENT ev_process_overdue_dues
    ON SCHEDULE EVERY 1 DAY
    STARTS TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL 1 DAY), '00:10:00')
    ON COMPLETION PRESERVE
    ENABLE
    COMMENT 'Marks unpaid dues as overdue after the deadline'
DO
BEGIN
    CALL sp_process_overdue_dues(@dues_marked);
END$$
DELIMITER ;


-- >>>>>>>>>> events/03_ev_expire_old_posts.sql
-- ====================================================================
-- ev_expire_old_posts
-- Runs every day. Open posts older than 30 days become expired.
-- ====================================================================
USE mess_finder;

DROP EVENT IF EXISTS ev_expire_old_posts;

DELIMITER $$
CREATE EVENT ev_expire_old_posts
    ON SCHEDULE EVERY 1 DAY
    STARTS TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL 1 DAY), '00:20:00')
    ON COMPLETION PRESERVE
    ENABLE
    COMMENT 'Expires vacancy and seat wanted posts older than 30 days'
DO
BEGIN
    CALL sp_expire_old_posts(@vacancy_expired, @wanted_expired);
END$$
DELIMITER ;


-- >>>>>>>>>> events/04_ev_cancel_missed_visits.sql
-- ====================================================================
-- ev_cancel_missed_visits
-- Runs every hour. A visit request that is still pending when the visit time
-- has passed was never answered by the manager, so it is cancelled.
-- ====================================================================
USE mess_finder;

DROP EVENT IF EXISTS ev_cancel_missed_visits;

DELIMITER $$
CREATE EVENT ev_cancel_missed_visits
    ON SCHEDULE EVERY 1 HOUR
    STARTS CURRENT_TIMESTAMP + INTERVAL 1 HOUR
    ON COMPLETION PRESERVE
    ENABLE
    COMMENT 'Cancels pending visit requests whose time has passed'
DO
BEGIN
    UPDATE visit_requests
       SET status = 'cancelled'
     WHERE status = 'pending'
       AND visit_time < NOW();
END$$
DELIMITER ;

